class Solution {
public:
    bool eval(TreeNode* node) {
        if (!node->left) return node->val == 1;
        bool l = eval(node->left);
        bool r = eval(node->right);
        return node->val == 2 ? (l || r) : (l && r);
    }
    bool evaluateTree(TreeNode* root) {
        return eval(root);
    }
};
